fields.InputDefinition:
{
  "goal": "Open the 'People' entity grid — type 'People' in the LEFT sidebar 'Search record types...' box and click the EXACT 'People' match (not 'Person Job Functions'/'Member Profiles'/'Memberships'); if that is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=MJ_BizApps_Common:%20People. Type 'Rodriguez' in the grid's filter box ('Filter records...'), click the row for Elena Rodriguez, then click 'Open Full Record'. The People form has related-records sections (for example Membership, Contact Methods, Relationships, Addresses, Job Functions). Open/expand ANY ONE related section; verify it displays her related rows (or a valid empty-state). Opening any one related section satisfies the goal — you do NOT need a specific one. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 50,
  "judgeValidationCriteria": [
    "A People record full form (Elena Rodriguez) is open",
    "At least one related-records section is shown with related rows or a valid empty-state",
    "No error messages, blank screens, or crash pages"
  ]
}
